 1→import { useState, useCallback, type KeyboardEvent } from 'react';
 2→import { useTranslation } from '../hooks/useTranslation';
 3→import './QueryEditor.css';
 4→
 5→interface QueryEditorProps {
 6→  onExecute: (sql: string) => Promise<void>;
 7→  initialQuery?: string;
 8→}
 9→
10→export function QueryEditor({ onExecute, initialQuery }: QueryEditorProps) {
11→  const { t } = useTranslation();
12→  const [sql, setSql] = useState(initialQuery ?? '');
13→  const [running, setRunning] = useState(false);
14→
15→  // Update when parent changes initialQuery
16→  const [prevInitial, setPrevInitial] = useState(initialQuery);
17→  if (initialQuery !== prevInitial) {
18→    setPrevInitial(initialQuery);
19→    if (initialQuery !== undefined) setSql(initialQuery);
20→  }
21→
22→  const run = useCallback(async () => {
23→    const trimmed = sql.trim();
24→    if (!trimmed || running) return;
25→    setRunning(true);
26→    try {
27→      await onExecute(trimmed);
28→    } finally {
29→      setRunning(false);
30→    }
31→  }, [sql, running, onExecute]);
32→
33→  const onKeyDown = useCallback(
34→    (e: KeyboardEvent) => {
35→      if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
36→        e.preventDefault();
37→        run();
38→      }
39→    },
40→    [run]
41→  );
42→
43→  return (
44→    <div className="query-editor">
45→      <textarea
46→        className="query-editor__textarea"
47→        value={sql}
48→        onChange={(e) => setSql(e.target.value)}
49→        onKeyDown={onKeyDown}
50→        placeholder={t('queryPlaceholder')}
51→        rows={6}
52→        spellCheck={false}
53→      />
54→      <div className="query-editor__actions">
55→        <button
56→          className="query-editor__run-btn"
57→          onClick={run}
58→          disabled={running || !sql.trim()}
59→        >
60→          {running ? t('running') : t('runQuery')}
61→        </button>
62→      </div>
63→    </div>
64→  );
65→}
