 1→import { useState } from 'react';
 2→import { createPortal } from 'react-dom';
 3→import { useTranslation } from '../hooks/useTranslation';
 4→import { createSkill } from '../services/skillsService';
 5→import './CreateSkillDialog.css';
 6→
 7→interface CreateSkillDialogProps {
 8→  onClose: () => void;
 9→  onCreated: () => void;
10→}
11→
12→export function CreateSkillDialog({ onClose, onCreated }: CreateSkillDialogProps) {
13→  const { t } = useTranslation();
14→  const [name, setName] = useState('');
15→  const [description, setDescription] = useState('');
16→  const [content, setContent] = useState('');
17→  const [error, setError] = useState('');
18→  const [saving, setSaving] = useState(false);
19→
20→  const handleSubmit = async () => {
21→    setError('');
22→    if (!name.trim() || !description.trim() || !content.trim()) {
23→      setError('All fields are required.');
24→      return;
25→    }
26→    setSaving(true);
27→    try {
28→      await createSkill({ name: name.trim(), description: description.trim(), content: content.trim() });
29→      onCreated();
30→      onClose();
31→    } catch (e) {
32→      setError(e instanceof Error ? e.message : 'Failed to create skill');
33→    } finally {
34→      setSaving(false);
35→    }
36→  };
37→
38→  return createPortal(
39→    <div className="create-skill-overlay" onClick={onClose}>
40→      <div className="create-skill-dialog" onClick={(e) => e.stopPropagation()}>
41→        <h3 className="create-skill-dialog__title">{t('createSkill')}</h3>
42→        {error && <p className="create-skill-dialog__error">{error}</p>}
43→        <label className="create-skill-dialog__label">{t('skillNameLabel')}</label>
44→        <input
45→          className="create-skill-dialog__input"
46→          value={name}
47→          onChange={(e) => setName(e.target.value)}
48→          placeholder={t('skillNamePlaceholder')}
49→        />
50→        <label className="create-skill-dialog__label">{t('skillDescriptionLabel')}</label>
51→        <input
52→          className="create-skill-dialog__input"
53→          value={description}
54→          onChange={(e) => setDescription(e.target.value)}
55→          placeholder={t('skillDescriptionPlaceholder')}
56→        />
57→        <label className="create-skill-dialog__label">{t('skillContentLabel')}</label>
58→        <textarea
59→          className="create-skill-dialog__textarea"
60→          value={content}
61→          onChange={(e) => setContent(e.target.value)}
62→          placeholder={t('skillContentPlaceholder')}
63→          rows={8}
64→        />
65→        <div className="create-skill-dialog__actions">
66→          <button className="create-skill-dialog__cancel" onClick={onClose}>{t('cancel')}</button>
67→          <button className="create-skill-dialog__save" onClick={handleSubmit} disabled={saving}>
68→            {saving ? '...' : t('createSkill')}
69→          </button>
70→        </div>
71→      </div>
72→    </div>,
73→    document.body
74→  );
75→}
