 34→  const [showCreateDialog, setShowCreateDialog] = useState(false);
 35→  const [skillsRefreshKey, setSkillsRefreshKey] = useState(0);
 36→  const [memoriesRefreshKey, setMemoriesRefreshKey] = useState(0);
 37→  const [tableSearchOpen, setTableSearchOpen] = useState(false);
 38→  const [tableSearch, setTableSearch] = useState('');
 39→
 40→  const toggle = (name: string) => {
 41→    setExpanded((prev) => ({ ...prev, [name]: !prev[name] }));
 42→  };
 43→
 44→  const filteredTables = useMemo(() => {
 45→    if (!tableSearch) return tables;
 46→    const q = tableSearch.toLowerCase();
 47→    return tables.filter((t) => t.name.toLowerCase().includes(q));
 48→  }, [tables, tableSearch]);
 49→
 50→  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
 51→    const files = e.target.files;
 52→    if (files && files.length > 0) {
 53→      onUpload(Array.from(files));
 54→    }
 55→    if (fileInputRef.current) {
 56→      fileInputRef.current.value = '';
 57→    }
 58→  };
 59→
 60→  return (
 61→    <>
 62→    <div className={`sidebar ${collapsed ? 'sidebar--collapsed' : ''}`}>
 63→      <div className="sidebar__top">
 64→        <div className="sidebar__header">
 65→          <div className="sidebar__tabs">
 66→            <button
 67→              className={`sidebar__tab ${activeTab === 'tables' ? 'sidebar__tab--active' : ''}`}
 68→              onClick={() => setActiveTab('tables')}
 69→            >
 70→              {t('tablesTab')}
 71→            </button>
 72→            <button
 73→              className={`sidebar__tab ${activeTab === 'skills' ? 'sidebar__tab--active' : ''}`}
 74→              onClick={() => setActiveTab('skills')}
 75→            >
 76→              {t('skillsTab')}
