122→                aria-label={t('deleteAllTables')}
123→                disabled={tables.length === 0}
124→              >
125→                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
126→                  <polyline points="3 6 5 6 21 6" />
127→                  <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
128→                </svg>
