  1→import { useState, useEffect, useCallback, useMemo } from 'react';
  2→import { createPortal } from 'react-dom';
  3→import ReactMarkdown from 'react-markdown';
  4→import remarkGfm from 'remark-gfm';
  5→import { useTranslation } from '../hooks/useTranslation';
  6→import { fetchSkills, fetchSkill, deleteSkill as apiDeleteSkill, toggleSkill as apiToggleSkill } from '../services/skillsService';
  7→import type { SkillInfo } from '../types';
  8→import './SkillsPanel.css';
  9→
 10→interface SkillsPanelProps {
 11→  onUseSkill: (skillName: string) => void;
 12→  onCreateClick: () => void;
 13→  refreshKey: number;
 14→}
 15→
 16→export function SkillsPanel({ onUseSkill, onCreateClick, refreshKey }: SkillsPanelProps) {
 17→  const { t } = useTranslation();
 18→  const [skills, setSkills] = useState<SkillInfo[]>([]);
 19→  const [selectedSkill, setSelectedSkill] = useState<SkillInfo | null>(null);
 20→  const [loadingDetail, setLoadingDetail] = useState<string | null>(null);
 21→  const [detailTab, setDetailTab] = useState<'preview' | 'source'>('preview');
 22→  const [searchOpen, setSearchOpen] = useState(false);
 23→  const [searchTerm, setSearchTerm] = useState('');
 24→
 25→  const loadSkills = useCallback(async () => {
 26→    try {
 27→      const data = await fetchSkills();
 28→      setSkills(data);
 29→    } catch {
 30→      // silently ignore
 31→    }
 32→  }, []);
 33→
 34→  useEffect(() => { loadSkills(); }, [loadSkills, refreshKey]);
 35→
 36→  useEffect(() => {
 37→    const handler = () => loadSkills();
 38→    window.addEventListener('skills-updated', handler);
 39→    return () => window.removeEventListener('skills-updated', handler);
 40→  }, [loadSkills]);
 41→
 42→  const filteredSkills = useMemo(() => {
 43→    if (!searchTerm) return skills;
 44→    const q = searchTerm.toLowerCase();
 45→    return skills.filter((s) => s.name.toLowerCase().includes(q) || (s.description && s.description.toLowerCase().includes(q)));
 46→  }, [skills, searchTerm]);
 47→
 48→  const handleSkillClick = async (name: string) => {
 49→    if (selectedSkill?.name === name) {
 50→      setSelectedSkill(null);
 51→      return;
 52→    }
 53→    setLoadingDetail(name);
 54→    setDetailTab('preview');
 55→    try {
 56→      const detail = await fetchSkill(name);
 57→      setSelectedSkill(detail);
 58→    } catch {
 59→      // silently ignore
 60→    } finally {
 61→      setLoadingDetail(null);
 62→    }
 63→  };
 64→
 65→  const handleDelete = async (name: string) => {
 66→    if (!confirm(t('deleteSkillConfirm', { name }))) return;
 67→    try {
 68→      await apiDeleteSkill(name);
 69→      setSkills((prev) => prev.filter((s) => s.name !== name));
 70→      if (selectedSkill?.name === name) setSelectedSkill(null);
 71→      window.dispatchEvent(new CustomEvent('skills-updated'));
 72→    } catch {
 73→      // silently ignore
 74→    }
 75→  };
 76→
 77→  const handleToggle = async (name: string, currentlyDisabled: boolean) => {
 78→    try {
 79→      const updated = await apiToggleSkill(name, !currentlyDisabled);
 80→      setSkills((prev) => prev.map((s) => s.name === name ? { ...s, disabled: updated.disabled } : s));
 81→      window.dispatchEvent(new CustomEvent('skills-updated'));
 82→    } catch {
 83→      // silently ignore
 84→    }
 85→  };
 86→
 87→  if (skills.length === 0) {
 88→    return (
 89→      <div className="skills-panel">
 90→        <div className="skills-panel__actions">
 91→          <button className="skills-panel__create-btn" onClick={onCreateClick} title={t('createSkill')}>
 92→            +
 93→          </button>
 94→        </div>
 95→        <p className="skills-panel__empty">{t('noSkills')}</p>
 96→      </div>
 97→    );
 98→  }
 99→
100→  return (
101→    <div className="skills-panel">
102→      <div className="skills-panel__actions">
103→        <button className="skills-panel__create-btn" onClick={onCreateClick} title={t('createSkill')}>
104→          +
105→        </button>
106→        <button
107→          className={`skills-panel__action-btn${searchOpen ? ' skills-panel__action-btn--active' : ''}`}
108→          onClick={() => { setSearchOpen((v) => !v); if (searchOpen) setSearchTerm(''); }}
109→          title={t('searchSkills')}
110→          aria-label={t('searchSkills')}
111→        >
112→          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
113→            <circle cx="11" cy="11" r="8" />
114→            <line x1="21" y1="21" x2="16.65" y2="16.65" />
115→          </svg>
116→        </button>
117→      </div>
118→      {searchOpen && (
119→        <input
120→          className="skills-panel__search-input"
121→          type="text"
122→          placeholder={t('searchSkillsPlaceholder')}
123→          value={searchTerm}
124→          onChange={(e) => setSearchTerm(e.target.value)}
125→          autoFocus
126→        />
127→      )}
128→      <ul className="skills-panel__list">
129→        {filteredSkills.map((skill) => (
130→          <li key={skill.name} className={`skills-panel__item${skill.disabled ? ' skills-panel__item--disabled' : ''}`} onClick={() => handleSkillClick(skill.name)}>
131→            <div className="skills-panel__item-header">
132→              <span className="skills-panel__name" title={skill.name}>
133→                {skill.name}
134→              </span>
135→              {loadingDetail === skill.name && <span className="skills-panel__loading">...</span>}
136→              {!skill.disabled && (
137→                <button
138→                  className="skills-panel__use-btn"
139→                  onClick={(e) => { e.stopPropagation(); onUseSkill(skill.name); }}
140→                >
141→                  {t('useSkill')}
142→                </button>
143→              )}
144→              <button
145→                className="skills-panel__toggle-btn"
146→                onClick={(e) => { e.stopPropagation(); handleToggle(skill.name, !!skill.disabled); }}
147→                title={skill.disabled ? t('enableSkill') : t('disableSkill')}
148→              >
149→                {skill.disabled ? (
150→                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/><path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
151→                ) : (
152→                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
153→                )}
154→              </button>
155→              {!skill.builtin && (
156→                <button
157→                  className="skills-panel__delete-btn"
158→                  onClick={(e) => { e.stopPropagation(); handleDelete(skill.name); }}
159→                  title={t('deleteSkill', { name: skill.name })}
160→                >
161→                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
162→                </button>
163→              )}
164→            </div>
165→            <p className="skills-panel__desc skills-panel__desc--truncated">
166→              {skill.description}
167→            </p>
168→          </li>
169→        ))}
170→      </ul>
171→
172→      {selectedSkill && createPortal(
173→        <div className="skill-detail-overlay" onClick={() => setSelectedSkill(null)}>
174→          <div className="skill-detail-modal" onClick={(e) => e.stopPropagation()}>
175→            <div className="skill-detail-modal__header">
176→              <span className="skill-detail-modal__name">{selectedSkill.name}</span>
177→              <button
178→                className="skills-panel__use-btn"
179→                onClick={() => { onUseSkill(selectedSkill.name); setSelectedSkill(null); }}
180→              >
181→                {t('useSkill')}
182→              </button>
183→              <button className="skill-detail-modal__close" onClick={() => setSelectedSkill(null)}>
184→                &times;
185→              </button>
186→            </div>
187→            <p className="skill-detail-modal__desc">{selectedSkill.description}</p>
188→            {selectedSkill.content && (
189→              <>
190→                <div className="skill-detail-modal__tabs">
191→                  <button
192→                    className={`skill-detail-modal__tab${detailTab === 'preview' ? ' skill-detail-modal__tab--active' : ''}`}
193→                    onClick={() => setDetailTab('preview')}
194→                  >
195→                    {t('skillPreview')}
196→                  </button>
197→                  <button
198→                    className={`skill-detail-modal__tab${detailTab === 'source' ? ' skill-detail-modal__tab--active' : ''}`}
199→                    onClick={() => setDetailTab('source')}
200→                  >
201→                    {t('skillSource')}
202→                  </button>
203→                </div>
204→                {detailTab === 'preview' ? (
205→                  <div className="skill-detail-modal__content skill-detail-modal__content--preview">
206→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{selectedSkill.content}</ReactMarkdown>
207→                  </div>
208→                ) : (
209→                  <pre className="skill-detail-modal__content">{selectedSkill.content}</pre>
210→                )}
211→              </>
212→            )}
213→          </div>
214→        </div>,
215→        document.body
216→      )}
217→    </div>
218→  );
219→}
