 23→function timeAgo(dateStr: string, t: (key: string, params?: Record<string, string | number>) => string): string {
 24→  const date = new Date(dateStr);
 25→  const now = new Date();
 26→  const seconds = Math.floor((now.getTime() - date.getTime()) / 1000);
 27→  if (seconds < 60) return t('timeJustNow');
 28→  const minutes = Math.floor(seconds / 60);
 29→  if (minutes < 60) return t('timeMinutesAgo', { count: minutes });
 30→  const hours = Math.floor(minutes / 60);
 31→  if (hours < 24) return t('timeHoursAgo', { count: hours });
 32→  const days = Math.floor(hours / 24);
 33→  if (days < 30) return t('timeDaysAgo', { count: days });
 34→  return date.toLocaleDateString();
 35→}
