.query-editor {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.query-editor__textarea {
  font-family: 'Courier New', Courier, monospace;
  font-size: 14px;
  padding: 12px;
  border: 1px solid var(--color-border-medium);
  border-radius: 6px;
  resize: vertical;
  outline: none;
  line-height: 1.5;
  background: var(--color-bg-primary);
  color: var(--color-text-primary);
}

.query-editor__textarea:focus {
  border-color: var(--color-accent-secondary);
  box-shadow: 0 0 0 2px var(--color-accent-secondary-shadow);
}

.query-editor__actions {
  display: flex;
  justify-content: flex-end;
}

.query-editor__run-btn {
  width: 100px;
  height: 38px;
  padding: 8px 20px;
  background: var(--color-accent-secondary);
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 14px;
  cursor: pointer;
  transition: background 0.2s;
  box-sizing: border-box;
  text-align: center;
}

.query-editor__run-btn:hover:not(:disabled) {
  background: var(--color-accent-secondary-hover);
}

.query-editor__run-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.chat-input {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid var(--color-border-light);
  background: var(--color-bg-primary);
}

.chat-input__textarea-wrapper {
  flex: 1;
  position: relative;
}

.chat-input__textarea {
  display: block;
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--color-border-dark);
  border-radius: 8px;
  font-size: 14px;
  font-family: inherit;
  resize: none;
  line-height: 1.4;
  max-height: 150px;
  background: var(--color-bg-primary);
  color: var(--color-text-primary);
  box-sizing: border-box;
}

.chat-input__shimmer {
  position: absolute;
  top: 1px;
  left: 1px;
  padding: 8px 12px;
  font-size: 14px;
  font-style: italic;
  line-height: 1.4;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    var(--color-text-disabled) 0%,
    var(--color-text-disabled) 40%,
    var(--color-accent-primary) 50%,
    var(--color-text-disabled) 60%,
    var(--color-text-disabled) 100%
  );
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: chat-input-shimmer 2s ease-in-out infinite;
}

@keyframes chat-input-shimmer {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}

.chat-input__textarea:focus {
  outline: none;
  border-color: var(--color-accent-primary);
  box-shadow: 0 0 0 2px var(--color-accent-primary-shadow);
}

.chat-input__textarea:disabled {
  background: var(--color-bg-secondary);
  color: var(--color-text-disabled);
}

.chat-input__send {
  align-self: flex-end;
  height: 38px;
  width: 64px;
  padding: 0 16px;
  background: var(--color-accent-primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  cursor: pointer;
  white-space: nowrap;
  box-sizing: border-box;
  text-align: center;
}

.chat-input__send:hover:not(:disabled) {
  background: var(--color-accent-primary-hover);
}

.chat-input__send:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.skills-panel {
  padding: 0;
}

.skills-panel__actions {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 0 8px;
}

.skills-panel__create-btn {
  background: none;
  border: 1px solid var(--color-border-medium);
  cursor: pointer;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  color: var(--color-text-muted);
  font-size: 18px;
  line-height: 1;
  transition: background 0.15s, color 0.15s;
}

.skills-panel__create-btn:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.skills-panel__action-btn {
  background: none;
  border: 1px solid var(--color-border-medium);
  cursor: pointer;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  color: var(--color-text-muted);
  transition: background 0.15s, color 0.15s;
}

.skills-panel__action-btn:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.skills-panel__action-btn--active {
  background: var(--color-accent-primary);
  color: #fff;
  border-color: var(--color-accent-primary);
}

.skills-panel__action-btn--active:hover {
  background: var(--color-accent-primary-hover);
  color: #fff;
}

.skills-panel__search-input {
  width: 100%;
  box-sizing: border-box;
  padding: 6px 10px;
  font-size: 13px;
  border: 1px solid var(--color-border-medium);
  border-radius: 6px;
  background: var(--color-bg-primary);
  color: var(--color-text-primary);
  margin-bottom: 8px;
  outline: none;
}

.skills-panel__search-input:focus {
  border-color: var(--color-accent-primary);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.skills-panel__empty {
  font-size: 13px;
  color: var(--color-text-faint);
  padding: 0;
  margin: 0;
}

.skills-panel__list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.skills-panel__item {
  margin-bottom: 8px;
  padding: 8px;
  border-radius: 6px;
  border: 1px solid var(--color-border-light);
  cursor: pointer;
}

.skills-panel__item:hover {
  border-color: var(--color-border-medium);
}

.skills-panel__item-header {
  display: flex;
  align-items: center;
  gap: 6px;
}

.skills-panel__name {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-primary);
  padding: 0;
  text-align: left;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-panel__loading {
  font-size: 12px;
  color: var(--color-text-muted);
}

.skills-panel__use-btn {
  background: var(--color-accent-primary);
  color: #fff;
  border: none;
  border-radius: 4px;
  font-size: 11px;
  width: 44px;
  height: 22px;
  padding: 2px 8px;
  cursor: pointer;
  white-space: nowrap;
  touch-action: manipulation;
  box-sizing: border-box;
  text-align: center;
}

.skills-panel__use-btn:hover {
  background: var(--color-accent-primary-hover);
}

.skills-panel__delete-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 16px;
  color: var(--color-text-muted);
  padding: 0 2px;
  opacity: 1;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

.skills-panel__delete-btn:hover {
  color: var(--color-error);
}

.skills-panel__desc {
  font-size: 12px;
  color: var(--color-text-muted);
  margin: 4px 0 0;
  line-height: 1.4;
}

.skills-panel__item--disabled {
  opacity: 0.5;
}

.skills-panel__toggle-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-text-muted);
  padding: 0 2px;
  line-height: 1;
  display: flex;
