  z-index: 1000;
}

.create-skill-dialog {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border-medium);
  border-radius: 12px;
  padding: 24px;
  width: 480px;
  max-width: 90vw;
  max-height: 80vh;
  overflow-y: auto;
}

.create-skill-dialog__title {
  margin: 0 0 16px;
  font-size: 16px;
  color: var(--color-text-primary);
}

.create-skill-dialog__error {
  color: var(--color-error);
  font-size: 13px;
  margin: 0 0 12px;
}

.create-skill-dialog__label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text-muted);
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.create-skill-dialog__input {
  display: block;
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--color-border-dark);
  border-radius: 6px;
  font-size: 14px;
  font-family: inherit;
  background: var(--color-bg-primary);
  color: var(--color-text-primary);
  margin-bottom: 12px;
  box-sizing: border-box;
}

.create-skill-dialog__textarea {
  display: block;
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--color-border-dark);
  border-radius: 6px;
  font-size: 13px;
  font-family: monospace;
  background: var(--color-bg-primary);
  color: var(--color-text-primary);
  margin-bottom: 16px;
  resize: vertical;
  box-sizing: border-box;
}

.create-skill-dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.create-skill-dialog__cancel {
  background: none;
  border: 1px solid var(--color-border-medium);
  border-radius: 6px;
  min-width: 80px;
  height: 34px;
  padding: 6px 16px;
  font-size: 14px;
  cursor: pointer;
  color: var(--color-text-primary);
  box-sizing: border-box;
  text-align: center;
  white-space: nowrap;
}

.create-skill-dialog__save {
  background: var(--color-accent-primary);
  color: #fff;
  border: none;
  border-radius: 6px;
  width: 100px;
  height: 34px;
  padding: 6px 16px;
  font-size: 14px;
  cursor: pointer;
  box-sizing: border-box;
  text-align: center;
}

.create-skill-dialog__save:hover:not(:disabled) {
  background: var(--color-accent-primary-hover);
}

.create-skill-dialog__save:disabled {
  opacity: 0.5;
}

