  color: var(--color-text-disabled);
}

.user-question__question {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  margin-bottom: 10px;
  line-height: 1.5;
}

.user-question__question p {
  margin: 0 0 8px;
}

.user-question__question p:last-child {
  margin-bottom: 0;
}

.user-question__question ul,
.user-question__question ol {
  margin: 4px 0 8px;
  padding-left: 20px;
}

.user-question__question li {
  margin-bottom: 2px;
}

.user-question__question code {
  background: var(--color-bg-primary);
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 13px;
}

.user-question__question pre {
  background: var(--color-bg-primary);
  padding: 8px 10px;
  border-radius: 6px;
  overflow-x: auto;
  margin: 4px 0 8px;
}

.user-question__question pre code {
  background: none;
  padding: 0;
}

.user-question__question strong {
  font-weight: 600;
}

.user-question__question h1,
.user-question__question h2,
.user-question__question h3,
.user-question__question h4 {
  margin: 8px 0 4px;
  font-weight: 600;
}

.user-question__question h1 { font-size: 16px; }
.user-question__question h2 { font-size: 15px; }
.user-question__question h3 { font-size: 14px; }
.user-question__question h4 { font-size: 14px; }

.user-question__options {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.user-question__option {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid var(--color-border-dark);
  border-radius: 6px;
  background: var(--color-bg-primary);
  cursor: pointer;
  text-align: left;
  font-size: 13px;
  color: var(--color-text-secondary);
  transition: border-color 0.15s, background 0.15s;
}

.user-question__option:hover {
  border-color: var(--color-accent-primary-border);
  background: var(--color-accent-primary-bg);
}

.user-question__option--selected {
  border-color: var(--color-accent-primary-light);
  background: var(--color-accent-primary-bg);
}

.user-question__checkbox {
  flex-shrink: 0;
  font-size: 16px;
}

.user-question__option-label {
  font-weight: 500;
}

.user-question__option-desc {
  display: block;
  font-size: 12px;
  color: var(--color-text-disabled);
  margin-top: 2px;
}

.user-question__free-text-toggle {
  margin-top: 8px;
}

.user-question__other-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 12px;
  color: var(--color-accent-primary-light);
  padding: 2px 0;
  text-decoration: underline;
}

.user-question__free-text {
  display: flex;
  gap: 8px;
  margin-top: 6px;
}

.user-question__free-text-input {
  flex: 1;
  padding: 6px 10px;
  border: 1px solid var(--color-border-dark);
  border-radius: 6px;
  font-size: 13px;
  background: var(--color-bg-primary);
  color: var(--color-text-secondary);
}

.user-question__free-text-input:focus {
  outline: none;
  border-color: var(--color-accent-primary-light);
}

.user-question__submit-btn {
  width: 72px;
  height: 32px;
  padding: 6px 14px;
  border: none;
  border-radius: 6px;
  background: var(--color-accent-primary-hover);
  color: var(--color-bg-primary);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s;
  box-sizing: border-box;
  text-align: center;
}

.user-question__submit-btn:hover {
  background: var(--color-accent-primary-active);
}

.user-question__submit-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.user-question__submit-multi {
  margin-top: 10px;
  width: 100%;
}

.user-question__selected-answers {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}

.user-question__selected-chip {
  padding: 3px 10px;
  border-radius: 12px;
  background: var(--color-success-bg);
  color: var(--color-success-text);
  font-size: 12px;
  font-weight: 500;
}

.file-upload-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
}

.file-upload {
  border: 2px dashed var(--color-border-dashed);
  border-radius: 8px;
  padding: 24px;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.2s, background-color 0.2s;
  width: 100%;
  box-sizing: border-box;
}

.file-upload:hover,
.file-upload--dragging {
  border-color: var(--color-accent-secondary);
  background-color: var(--color-bg-hover);
}

.file-upload__input {
  display: none;
}

.file-upload__text {
  margin: 0;
  color: var(--color-text-muted);
  font-size: 14px;
}

.file-upload-divider {
  display: flex;
  align-items: center;
  width: 100%;
  margin: 12px 0;
}

.file-upload-divider::before,
.file-upload-divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--color-border-medium);
}

.file-upload-divider span {
  padding: 0 12px;
  color: var(--color-text-faint);
  font-size: 13px;
}

.file-upload-sample-btn {
  width: 240px;
  height: 40px;
  padding: 8px 20px;
  border: 1px solid var(--color-accent-secondary);
  border-radius: 6px;
  background: transparent;
  color: var(--color-accent-secondary);
  font-size: 14px;
  line-height: 1.5;
  cursor: pointer;
  transition: background-color 0.2s, color 0.2s;
  box-sizing: border-box;
  text-align: center;
}

.file-upload-sample-btn:hover:not(:disabled) {
  background-color: var(--color-accent-secondary);
  color: #fff;
}

.file-upload-sample-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.agent-panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: var(--color-bg-secondary);
}

.agent-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  border-bottom: 1px solid var(--color-border-light);
  background: var(--color-bg-primary);
}

.agent-panel__title {
  font-size: 15px;
  font-weight: 700;
  color: var(--color-text-secondary);
}

.agent-panel__clear {
  height: 28px;
  padding: 0 10px;
  font-size: 12px;
  background: none;
  border: 1px solid var(--color-border-dark);
  border-radius: 6px;
  color: var(--color-text-subtle);
  cursor: pointer;
  box-sizing: border-box;
  text-align: center;
  white-space: nowrap;
}

.agent-panel__clear:hover {
  background: var(--color-bg-code);
  color: var(--color-text-tertiary);
}

.agent-panel__actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  width: 210px;
}

.agent-panel__langfuse {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 28px;
  width: 80px;
  padding: 0 10px;
  font-size: 12px;
  background: none;
  border: 1px solid var(--color-border-dark);
  border-radius: 6px;
  color: var(--color-text-subtle);
  cursor: pointer;
  box-sizing: border-box;
}

.agent-panel__langfuse-icon {
  width: 14px;
  height: 14px;
}

.agent-panel__langfuse:hover:not(:disabled) {
  background: var(--color-bg-code);
  color: var(--color-text-tertiary);
}

.agent-panel__langfuse--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.agent-panel__messages {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

.agent-panel__empty {
  text-align: center;
  color: var(--color-text-disabled);
  font-size: 14px;
  margin-top: 40px;
  padding: 0 20px;
  line-height: 1.5;
}

.query-editor {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.query-editor__textarea {
  font-family: 'Courier New', Courier, monospace;
  font-size: 14px;
  padding: 12px;
  border: 1px solid var(--color-border-medium);
  border-radius: 6px;
  resize: vertical;
  outline: none;
  line-height: 1.5;
  background: var(--color-bg-primary);
  color: var(--color-text-primary);
}

.query-editor__textarea:focus {
  border-color: var(--color-accent-secondary);
  box-shadow: 0 0 0 2px var(--color-accent-secondary-shadow);
}

.query-editor__actions {
  display: flex;
  justify-content: flex-end;
}

.query-editor__run-btn {
  min-width: 100px;
  height: 38px;
  padding: 8px 20px;
  background: var(--color-accent-secondary);
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 14px;
  cursor: pointer;
  transition: background 0.2s;
  box-sizing: border-box;
  text-align: center;
  white-space: nowrap;
}

.query-editor__run-btn:hover:not(:disabled) {
  background: var(--color-accent-secondary-hover);
}

.query-editor__run-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

